package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/gorilla/websocket"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

type WSMessage struct {
	Action  string            `json:"action"`
	Headers map[string]string `json:"headers"`
	Payload string            `json:"payload"`
}

type StreamService struct {
	grpcConn *grpc.ClientConn
}

func NewStreamService(target string) *StreamService {
	conn, err := grpc.Dial(target, grpc.WithInsecure())
	if err != nil {
		log.Fatalf("failed to connect: %v", err)
	}
	return &StreamService{grpcConn: conn}
}

// handleWebSocket processes real-time messages from clients
func (s *StreamService) handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, message, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg WSMessage
		if err := json.Unmarshal(message, &msg); err != nil {
			conn.WriteMessage(websocket.TextMessage, []byte(`{"error":"invalid json"}`))
			continue
		}

		response := s.processMessage(msg)
		conn.WriteMessage(websocket.TextMessage, response)
	}
}

// processMessage routes actions to gRPC backend with user-supplied metadata
func (s *StreamService) processMessage(msg WSMessage) []byte {
	// Build gRPC metadata from client-supplied headers
	// This allows clients to pass correlation IDs, auth tokens, etc.
	md := metadata.New(map[string]string{})

	for key, value := range msg.Headers {
		// Basic sanitization - remove newlines to prevent header injection
		sanitized := strings.ReplaceAll(value, "\n", "")
		sanitized = strings.ReplaceAll(sanitized, "\r", "")
		md.Append(strings.ToLower(key), sanitized)
	}

	ctx := metadata.NewOutgoingContext(context.Background(), md)

	// Forward to gRPC backend
	var header metadata.MD
	err := s.grpcConn.Invoke(ctx, "/stream.Service/Process", msg.Payload, nil, grpc.Header(&header))
	if err != nil {
		errResp, _ := json.Marshal(map[string]string{"error": err.Error()})
		return errResp
	}

	// Reflect response headers back to WebSocket client as HTML notification
	notification := buildNotification(header)
	return notification
}

// buildNotification creates an HTML snippet from gRPC response metadata
// This is rendered in the client's notification panel
func buildNotification(header metadata.MD) []byte {
	var builder strings.Builder
	builder.WriteString(`<div class="notification">`)

	if vals := header.Get("x-notification-title"); len(vals) > 0 {
		// Title is rendered directly - trusted from backend
		builder.WriteString(fmt.Sprintf(`<h3>%s</h3>`, vals[0]))
	}
	if vals := header.Get("x-notification-body"); len(vals) > 0 {
		builder.WriteString(fmt.Sprintf(`<p>%s</p>`, vals[0]))
	}
	if vals := header.Get("x-notification-action"); len(vals) > 0 {
		// Action URL for the notification button
		builder.WriteString(fmt.Sprintf(`<a href="%s" class="btn">View</a>`, vals[0]))
	}

	builder.WriteString(`</div>`)

	resp, _ := json.Marshal(map[string]string{
		"type": "notification",
		"html": builder.String(),
	})
	return resp
}

func main() {
	svc := NewStreamService("localhost:50051")

	http.HandleFunc("/ws", svc.handleWebSocket)
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	})

	log.Println("WebSocket service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
